Use Node’s built-in `http.request()` with the `socketPath` option:

```js
import { createServer, request } from 'node:http';

const socketPath = '/tmp/example.sock';

const server = createServer((_req, res) => {
  res.end('Hello from node:http');
});

server.listen(socketPath, () => {
  const req = request(
    {
      socketPath,
      path: '/',
    },
    (res) => {
      res.on('data', chunk => process.stdout.write(String(chunk)));
      res.on('end', () => server.close());
    }
  );

  req.end();
});
```

For an existing Unix-socket HTTP service, use the same client options:

```js
import http from 'node:http';

const req = http.request({
  socketPath: '/var/run/docker.sock',
  path: '/containers/json',
  method: 'GET',
}, (res) => {
  let body = '';

  res.on('data', chunk => body += chunk);
  res.on('end', () => console.log(body));
});

req.on('error', console.error);
req.end();
```

The Unix socket path is specified with `socketPath`; the request path is specified separately with `path`.
